{
  "name": "Cobolt 06-01 激光器",
  "name_en": "Cobolt 06-01 Laser",
  "manufacturer": "Cobolt",
  "description": "这是一款紧凑型实验室激光光源，可提供受控的激光输出功率，并支持调制工作模式。它常用于显微成像、荧光激发、光学对准及其他需要稳定激光照明或激发光的实验与仪器系统。",
  "description_en": "This is a compact laboratory laser source that provides controlled optical output power and supports modulation operating modes. It is commonly used for microscopy, fluorescence excitation, optical alignment, and other experiments or instruments that require stable laser illumination or excitation light.",
  "tag_hints": [
    "laser source",
    "APC power control",
    "digital modulation",
    "optical excitation",
    "microscopy illumination",
    "laser power setpoint"
  ],
  "actions": [
    {
      "action_name": "auto-idn",
      "description": "获取激光器的身份识别信息。",
      "description_en": "Get the laser identification information."
    },
    {
      "action_name": "auto-status",
      "description": "获取设备当前状态。",
      "description_en": "Get the current device status."
    },
    {
      "action_name": "auto-enabled",
      "description": "获取或设置激光发射启用状态。",
      "description_en": "Get or set the laser emission enabled state."
    },
    {
      "action_name": "auto-power_sp",
      "description": "获取或设置 APC 模式下的输出功率设定值（mW）。",
      "description_en": "Get or set the output power setpoint (mW) in APC mode."
    },
    {
      "action_name": "auto-power",
      "description": "获取当前激光输出功率（mW）。",
      "description_en": "Get the current laser output power (mW)."
    },
    {
      "action_name": "auto-enter_mod_mode",
      "description": "使激光器进入调制模式。",
      "description_en": "Put the laser into modulation mode."
    },
    {
      "action_name": "auto-digital_mod",
      "description": "获取或设置数字调制启用状态。",
      "description_en": "Get or set the digital modulation enabled state."
    },
    {
      "action_name": "auto-mod_mode",
      "description": "获取当前工作模式。",
      "description_en": "Get the current operating mode."
    },
    {
      "action_name": "auto-power_mod",
      "description": "获取或设置功率调制参数。",
      "description_en": "Get or set the power modulation setting."
    },
    {
      "action_name": "auto-query",
      "description": "向激光器发送文本查询命令并读取返回信息。",
      "description_en": "Send a text query command to the laser and read back the response."
    }
  ]
}

